     // The stack wraps one registration, which sees the broker\'s own message.\n        b.include_router(Router::new().include(accept).layer(stack));\n    })\n}\n'})})}),(0,a.jsx)(i.A,{value:"manual",label:"Manual",children:(0,a.jsx)(n.pre,{children:(0,a.jsx)(n.code,{className:"language-rust",metastring:'title="https://github.com/powersemmi/ruststream/blob/main/examples/manual/dyn_stack.rs"',children:'struct Accept;\n\nimpl Handle<Order> for Accept {\n    fn handle(\n        &self,\n        order: &Order,\n        _outs: &(),\n        _ctx: &mut Context<\'_>,\n    ) -> impl Future<Output = Result<(), HandlerOutcome>> {\n        tracing::info!(order.id, "accepted");\n        ready(Ok(()))\n    }\n}\n\n/// The chain comes from configuration: one `Block` per tenant the operator listed.\nfn app(blocked: &[&str]) -> impl App {\n    let chain = blocked\n        .iter()\n        .map(|tenant| -> Arc<dyn DynMiddleware<MemoryMessage>> {\n            Arc::new(Block {\n                tenant: (*tenant).to_owned(),\n            })\n        });\n    let stack = DynStack::new(chain);\n    RustStream::new(AppInfo::new("orders", "0.1.0")).with_broker(MemoryBroker::new(), |b| {\n        // The stack wraps one registration, which sees the broker\'s own message.\n        b.include_router(\n            Router::new()\n                .include(subscriber("orders", Accept).build())\n                .layer(stack),\n        );\n    })\n}\n'})})})]})]})}function m(e={}){let{wrapper:n}={...(0,s.R)(),...e.components};return n?(0,a.jsx)(n,{...e,children:(0,a.jsx)(h,{...e})}):h(e)}},57250(e,n,t){t.d(n,{A:()=>i});var r=t(74848);t(96540);var a=t(34164),s=t(57663);function o({children:e,className:n,hidden:t}){return(0,r.jsx)("div",{role:"tabpanel",className:(0,a.A)("tabItem_Ymn6",n),hidden:t,children:e})}function i({children:e,className:n,value:t}){let{selectedValue:a,lazy:l}=(0,s.uc)(),c=t===a;return!c&&l?null:(0,r.jsx)(o,{className:n,hidden:!c,children:e})}},50773(e,n,t){t.d(n,{A:()=>h});var r=t